import os
from typing import Any, Dict, List, Optional

from pydantic import BaseModel, Field, ValidationError, field_validator
from openai import OpenAI


class ExtractedField(BaseModel):
    value: Optional[str] = None
    confidence: float = Field(ge=0.0, le=1.0)

    @field_validator("value")
    @classmethod
    def normalize_value(cls, v: Optional[str]) -> Optional[str]:
        if v is None:
            return None
        v = v.strip()
        return v or None


class DocumentExtraction(BaseModel):
    invoice_number: ExtractedField
    invoice_date: ExtractedField
    vendor_name: ExtractedField
    total_amount: ExtractedField

    @field_validator("invoice_number", "invoice_date", "vendor_name", "total_amount")
    @classmethod
    def required_value_present(cls, field_obj: ExtractedField) -> ExtractedField:
        if field_obj.value is None:
            raise ValueError("required field value is missing")
        return field_obj


class StructuredExtractionResult(BaseModel):
    valid: bool
    data: Optional[DocumentExtraction] = None
    errors: List[str] = Field(default_factory=list)
    raw_response: Optional[Dict[str, Any]] = None


def extract_structured_document(document_text: str) -> StructuredExtractionResult:
    client = OpenAI(api_key=os.environ["OPENAI_API_KEY"])

    schema = {
        "type": "object",
        "additionalProperties": False,
        "properties": {
            "invoice_number": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "value": {"type": ["string", "null"]},
                    "confidence": {"type": "number", "minimum": 0, "maximum": 1},
                },
                "required": ["value", "confidence"],
            },
            "invoice_date": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "value": {"type": ["string", "null"]},
                    "confidence": {"type": "number", "minimum": 0, "maximum": 1},
                },
                "required": ["value", "confidence"],
            },
            "vendor_name": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "value": {"type": ["string", "null"]},
                    "confidence": {"type": "number", "minimum": 0, "maximum": 1},
                },
                "required": ["value", "confidence"],
            },
            "total_amount": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "value": {"type": ["string", "null"]},
                    "confidence": {"type": "number", "minimum": 0, "maximum": 1},
                },
                "required": ["value", "confidence"],
            },
        },
        "required": ["invoice_number", "invoice_date", "vendor_name", "total_amount"],
    }

    response = client.responses.create(
        model="gpt-4.1-mini",
        input=[
            {
                "role": "system",
                "content": (
                    "Extract structured invoice fields from the provided document text. "
                    "Return only the requested JSON. "
                    "Confidence must be a number between 0 and 1 for each field. "
                    "If a field cannot be found, set its value to null and provide the best confidence estimate."
                ),
            },
            {
                "role": "user",
                "content": document_text,
            },
        ],
        text={
            "format": {
                "type": "json_schema",
                "name": "invoice_extraction",
                "schema": schema,
                "strict": True,
            }
        },
    )

    raw_output = None
    try:
        raw_output = response.output[0].content[0].parsed
    except Exception:
        try:
            raw_output = response.output_parsed
        except Exception:
            raw_output = None

    if raw_output is None:
        return StructuredExtractionResult(
            valid=False,
            errors=["failed to parse structured response from OpenAI API"],
            raw_response={"response_id": getattr(response, "id", None)},
        )

    try:
        validated = DocumentExtraction.model_validate(raw_output)
        return StructuredExtractionResult(
            valid=True,
            data=validated,
            errors=[],
            raw_response=raw_output,
        )
    except ValidationError as e:
        return StructuredExtractionResult(
            valid=False,
            errors=[err["msg"] for err in e.errors()],
            raw_response=raw_output,
        )
